import React, { useState, useEffect, useCallback } from "react";
import {
  ServerIcon,
  ClockIcon,
  ExclamationTriangleIcon,
  CheckCircleIcon,
  XCircleIcon,
  ArrowPathIcon,
  ChartBarIcon,
} from "@heroicons/react/24/outline";
import { apiService, dataUtils } from "../services/api";
import StatusBadge, { StatusPulse, StatusDot } from "../components/StatusBadge";
import MetricCard from "../components/MetricCard";
import toast from "react-hot-toast";

const Services = () => {
  const [services, setServices] = useState([]);
  const [prometheusTargets, setPrometheusTargets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [lastUpdated, setLastUpdated] = useState(new Date());

  // Service configuration
  const serviceConfig = [
    {
      name: "auth_service",
      displayName: "Auth Service",
      port: 8001,
      metricsPort: 8002,
      description: "User authentication and authorization",
      icon: "🔐",
    },
    {
      name: "catalog_service",
      displayName: "Catalog Service",
      port: 8005,
      metricsPort: 8006,
      description: "Product catalog management",
      icon: "📦",
    },
    {
      name: "order_service",
      displayName: "Order Service",
      port: 8003,
      metricsPort: 8004,
      description: "Order processing and management",
      icon: "🛒",
    },
  ];

  // Fetch service data
  const fetchServiceData = useCallback(async () => {
    try {
      setLoading(true);
      const [summaryData, prometheusData] = await Promise.all([
        apiService.getSummary(),
        apiService.getPrometheusStatus()
      ]);
      
      setServices(summaryData.services || []);
      setPrometheusTargets(prometheusData.targets || []);
      setLastUpdated(new Date());
    } catch (error) {
      console.error('Failed to fetch service data:', error);
      toast.error('Failed to load service data');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchServiceData();
    const interval = setInterval(fetchServiceData, 30000); // Update every 30 seconds
    return () => clearInterval(interval);
  }, [fetchServiceData]);

  // Manual refresh
  const handleRefresh = () => {
    fetchServiceData();
    toast.success("Service data refreshed");
  };

  // Get service metrics
  const getServiceMetrics = (service) => {
    return [
      {
        title: "Response Time",
        value: `${service.responseTime}ms`,
        subtitle: "Average",
        color: service.responseTime > 300 ? "warning" : "success",
      },
      {
        title: "Requests/min",
        value: dataUtils.formatNumber(service.requestsPerMinute),
        subtitle: "Throughput",
        color: "primary",
      },
      {
        title: "Error Rate",
        value: `${service.errorRate}%`,
        subtitle: "Last hour",
        color: service.errorRate > 2 ? "danger" : "success",
      },
      {
        title: "Uptime",
        value: `${service.uptime}%`,
        subtitle: "Last 24h",
        color: service.uptime > 99 ? "success" : "warning",
      },
    ];
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Service Health</h1>
          <p className="text-gray-600">
            Monitor individual service status and performance
          </p>
        </div>
        <div className="flex items-center space-x-4">
          <div className="text-sm text-gray-500">
            Last updated: {lastUpdated.toLocaleTimeString()}
          </div>
          <button
            onClick={handleRefresh}
            disabled={loading}
            className="btn btn-primary"
          >
            <ArrowPathIcon
              className={`w-4 h-4 mr-2 ${loading ? "animate-spin" : ""}`}
            />
            {loading ? "Loading..." : "Refresh"}
          </button>
        </div>
      </div>

      {/* Prometheus Status */}
      {prometheusTargets.length > 0 && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Prometheus Status</h2>
            <StatusBadge status="healthy" />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div className="text-center">
              <div className="text-2xl font-bold text-gray-900">
                {prometheusTargets.length}
              </div>
              <div className="text-sm text-gray-500">Targets</div>
            </div>

            <div className="text-center">
              <div className="text-2xl font-bold text-gray-900">
                {services.length}
              </div>
              <div className="text-sm text-gray-500">Services</div>
            </div>
          </div>
        </div>
      )}

      {/* Service Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
        {services.map((service) => (
          <div key={service.name} className="card">
            {/* Service Header */}
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center space-x-3">
                <div className="text-2xl">{service.icon}</div>
                <div>
                  <h3 className="text-lg font-semibold text-gray-900">
                    {service.displayName}
                  </h3>
                  <p className="text-sm text-gray-500">{service.description}</p>
                </div>
              </div>
              <StatusPulse status={service.status} />
            </div>

            {/* Service Status */}
            <div className="grid grid-cols-2 gap-4 mb-4">
              <div className="text-center p-3 bg-gray-50 rounded-lg">
                <div className="text-sm text-gray-500">Status</div>
                <StatusBadge status={service.status} size="sm" />
              </div>

              <div className="text-center p-3 bg-gray-50 rounded-lg">
                <div className="text-sm text-gray-500">Prometheus</div>
                <StatusDot
                  status={
                    service.prometheusTarget?.health === "up"
                      ? "healthy"
                      : "unhealthy"
                  }
                  size="md"
                />
              </div>
            </div>

            {/* Service Metrics */}
            <div className="space-y-3">
              {getServiceMetrics(service).map((metric, index) => (
                <div key={index} className="flex justify-between items-center">
                  <span className="text-sm text-gray-600">{metric.title}</span>
                  <div className="flex items-center space-x-2">
                    <span
                      className={`text-sm font-medium ${
                        metric.color === "danger"
                          ? "text-danger-600"
                          : metric.color === "warning"
                          ? "text-warning-600"
                          : metric.color === "success"
                          ? "text-success-600"
                          : "text-primary-600"
                      }`}
                    >
                      {metric.value}
                    </span>
                    <span className="text-xs text-gray-400">
                      {metric.subtitle}
                    </span>
                  </div>
                </div>
              ))}
            </div>

            {/* Service Actions */}
            <div className="mt-4 pt-4 border-t border-gray-200">
              <div className="flex space-x-2">
                <button className="btn btn-secondary text-xs">View Logs</button>
                <button className="btn btn-primary text-xs">
                  View Metrics
                </button>
                <button className="btn btn-warning text-xs">
                  Health Check
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Prometheus Targets */}
      {prometheusTargets.length > 0 && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Prometheus Targets</h2>
          </div>

          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Service
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Target
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Status
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Last Scrape
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Labels
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {prometheusTargets.map((target, index) => (
                  <tr key={index} className="hover:bg-gray-50">
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                      {target.labels?.service ||
                        target.scrapeUrl?.split(":")[0]}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {target.scrapeUrl}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <StatusBadge
                        status={
                          target.health === "up" ? "healthy" : "unhealthy"
                        }
                        size="sm"
                      />
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {target.lastScrape
                        ? new Date(target.lastScrape).toLocaleTimeString()
                        : "Never"}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {Object.entries(target.labels || {}).map(
                        ([key, value]) => (
                          <span
                            key={key}
                            className="inline-block bg-gray-100 rounded px-2 py-1 text-xs mr-1"
                          >
                            {key}={value}
                          </span>
                        )
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default Services;
